  // Test 2: Multiple params
  ccxt::any result2 =
      exchange.extractParams(std::string("/users/{user_id}/orders/{order_id}"));
  assertDeepEqual(exchange, ccxt::any{}, std::string("testExtractParams"),
                  result2,
                  ccxt::list{std::string("user_id"), std::string("order_id")});
